"""API request/response contracts for persistent AI writing suggestions."""
from datetime import datetime
from typing import Literal

from pydantic import BaseModel, Field

SuggestionTypeLiteral = Literal[
    "grammar", "clarity", "tone", "wordiness", "repetition", "alternative", "rewrite", "other",
    "spelling", "conciseness", "readability", "word_choice",
]
SuggestionStatusLiteral = Literal["pending", "accepted", "rejected"]


class SuggestionCreate(BaseModel):
    """Request to store a suggestion generated by the AI."""

    type: SuggestionTypeLiteral = "other"
    original_text: str = Field(default="", max_length=10000)
    suggested_text: str = Field(default="", max_length=10000)
    reason: str | None = Field(default=None, max_length=500)
    document_revision: int = Field(default=0, ge=0, strict=True)


class SuggestionUpdate(BaseModel):
    """Request to accept or reject a suggestion.

    ``base_revision`` is required when accepting so the backend can detect a
    stale document (the suggestion was made against an older revision and the
    document has since changed). Rejecting does not require it.
    """

    status: Literal["accepted", "rejected"]
    base_revision: int | None = Field(default=None, ge=0, strict=True)


class SuggestionOut(BaseModel):
    """Full suggestion record returned to the frontend."""

    id: str
    document_id: str
    user_id: str
    type: SuggestionTypeLiteral
    original_text: str
    suggested_text: str
    reason: str | None = None
    status: SuggestionStatusLiteral
    document_revision: int
    created_at: datetime | None = None
    resolved_at: datetime | None = None
    resolved_by: str | None = None
